from __future__ import absolute_import, division, print_function,\
    unicode_literals

from builtins import range, str, int, object
from contextlib import contextmanager

import time

from taf.ul.trs_e2e_fw.lib.call_utils.module.exceptions import SerialConnectionException
from taf.ul.trs_e2e_fw.lib.remote_connection.telnet_library.telnet_controller import TelnetController
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable

logger = BackgroundLogger.Instance()


class Serial_Access(object):
    """
    Class represent functionalities required for serial communication
    """

    def __init__(self, ssh_session_to_dongle_host):
        self.ssh_session_to_dongle_host = ssh_session_to_dongle_host

    @contextmanager
    def new_serial_2tcp_connection(self, ttydevice, rat, device_config_name, remote_port):
        """
        Function to start new serial2tcp connection
        """
        try:
            self.telnet_session = self._open_serial_connection_and_start_telnet(
                ttydevice, rat, device_config_name, remote_port)
            yield
        except Exception as err:
            # logger.debug('exception raised inside new_serial_2tcp_connection func')
            raise err
        finally:
            self._close_serial_connection()

    def _open_serial_connection_and_start_telnet(self, ttydevice, rat, dongle_config_name,
                                                 remote_port, max_attempts=4):
        remote_port = remote_port
        dongle_config_details = get_config_variable(["ue_devices", rat, dongle_config_name])
        remote_host = dongle_config_details.get('remote_ip', '127.0.0.1')
        # tty_path = dongle_config_details.get('tty_path', '/dev/ttyUSB1')
        try:
            remote_port = self._open_serial_connection(max_attempts, remote_host, remote_port,
                                                       ttydevice)
        except Exception as err:
            logger.debug('Serial Connection Error to {} \n\t{}'.format(ttydevice, err))
            raise err
        time.sleep(3)
        return self._start_telnet(dongle_config_details, remote_host, remote_port)

    def _start_telnet(self, dongle_config_details, remote_host, remote_port):
        telnet_session = None
        for attempt in range(1, 4):
            try:
                logger.debug('Telnet Attempt {}'.format(attempt))
                telnet_session = TelnetController()
                telnet_session.setup_telnet_remote_access(host=remote_host,
                                                          user=dongle_config_details
                                                          .get('remote_user', ''),
                                                          password=dongle_config_details
                                                          .get('remote_password', ''),
                                                          port=remote_port, prompt='', timeout=10)
                return telnet_session
            except Exception as err:
                logger.debug('Exception Occurred: {}\n'.format(err))
                continue

    def _open_serial_connection(self, max_attempts, remote_host, remote_port, ttydevice):
        for port in range(remote_port, remote_port + max_attempts):
            logger.debug('Serial Connection Attempt')
            cmd = 'serial2tcp -p {} -l {} -P {} > serial2tcp.log 2>&1 & echo $!'\
                .format(ttydevice, remote_host, port)
            logger.debug(cmd)
            (stdin, console_output, stderr) = self.ssh_session_to_dongle_host.exec_command(cmd)
            self.serail2tcp_process_id = int(console_output.readline())
            logger.debug("Serial to TCP Process ID: {0}".format(self.serail2tcp_process_id))
            time.sleep(5)
            cmd = 'cat serial2tcp.log'
            (stdin, console_output, stderr) = self.ssh_session_to_dongle_host.exec_command(cmd)
            console_output = console_output.readlines()
            logger.debug("Serial2tcp log output:\n{0}".format(console_output))
            if "No such file or directory: '{}'".format(ttydevice) in str(console_output):
                raise SerialConnectionException('{} doesnot exist'.format(ttydevice))
            elif 'Waiting for connection' in str(console_output):
                return port
            else:
                continue
        else:
            raise SerialConnectionException()

    def _close_serial_connection(self):
        if self.telnet_session.store.has_alias('default'):
            self.telnet_session.teardown_telnet_remote_access()
        cmd = "kill -2 {}".format(self.serail2tcp_process_id)
        logger.debug("Stopping serial2tcp. Command : {}".format(cmd))
        (stdin, console_output, stderr) = self.ssh_session_to_dongle_host.exec_command(cmd)
        time.sleep(5)   # give sometime for the serial2tcp to be fully closed
        # logger.debug('serial connection close console output: {}'
        # .format(console_output.readlines))
        logger.debug('Serial connection closed explicitly')

    def write_command_and_return_output(self, command, timeout=60):
        """
        Function to write command and return output
        """
        logger.debug('{}'.format(command))
        output = self.telnet_session.execute_command_on_host(command=command, timeout=timeout,
                                                             prompt='OK')
        logger.debug("AT command output: {}".format(output))
        return output